package care.tend.dashboard;
import care.tend.checkin.*;import care.tend.common.CurrentUser;import care.tend.item.*;import org.springframework.web.bind.annotation.*;import java.time.*;import java.util.*;
@RestController@RequestMapping("/api/dashboard")public class DashboardController{private final LifeItemRepository items;private final CheckinRepository checkins;public DashboardController(LifeItemRepository items,CheckinRepository checkins){this.items=items;this.checkins=checkins;}record Response(List<LifeItem> today,WellbeingCheckin latestCheckin,Map<String,Long> counts,String suggestion){}
 @GetMapping Response get(){var uid=CurrentUser.id();var c=checkins.findFirstByUserIdOrderByRecordedAtDesc(uid).orElse(null);var energy=c==null?"MODERATE":c.energy;var suggestion=switch(energy.toUpperCase()){case"LOW"->"Choose one gentle priority and its minimum action.";case"HIGH"->"You may have room for three priorities, with breaks.";default->"Two meaningful priorities may be enough today.";};return new Response(items.today(uid,LocalDate.now()),c,Map.of("goals",items.countByUserIdAndTypeAndStatus(uid,LifeItem.Type.GOAL,"ACTIVE"),"tasks",items.countByUserIdAndTypeAndStatus(uid,LifeItem.Type.TASK,"ACTIVE"),"habits",items.countByUserIdAndTypeAndStatus(uid,LifeItem.Type.HABIT,"ACTIVE")),suggestion);}}
